/** Asset module ids (Metro `require` results) for one prepared character. */
export interface ModelEntry {
  glb: number;
  animations: string[];
  /** material name -> texture slot -> .lwtex asset */
  materials: Record<string, Partial<Record<TextureSlot, number>>>;
}

export type TextureSlot = 'map' | 'normalMap' | 'roughnessMap';

/** Shape of assets/models/index.js (generated by tools/prepare-models.mjs). */
export interface ModelManifest {
  jason?: ModelEntry;
  elena?: ModelEntry;
}
